@import "tailwindcss";

/* ===== THEME TOKENS (Tailwind v4) ===== */
@theme {
  /* Primary Green (AI Theme) */
  --color-primary-500: #10b981;   /* emerald-500 */
  --color-primary-400: #34d399;
  --color-primary-300: #6ee7b7;

  /* Dark Background Scale */
